oracle=obj({'oracle_id':string,'kind':S('string',enum=['SYMBOLIC','NUMERICAL','DIMENSIONAL','PHYSICS','CHEMISTRY','ENGINEERING','HUMAN']),'fixture_ids':ids,'has_negative':S('boolean'),'has_inconclusive':S('boolean'),'domain_policy':string,'tolerance_policy':string,'runtime_isolation':S('string',enum=['PROCESS_LIMITED','PREVALIDATED','HUMAN_REVIEW'])})
variant=obj({'variant_id':string,'family':string,'representation':S('string',enum=['ALGEBRAIC','GRAPHICAL','TABULAR','VERBAL','SIMULATION','DIAGRAM','OTHER']),'role':S('string',enum=['PRACTICE','TRANSFER','EXAM','LAB']),'item_id':string})
feedback=obj({'misconception_id':string,'rule':string,'diagnostic_question':string,'remediation':string,'explanation':string})
activity=obj({'activity_id':string,'course_id':string,'course_version':string,'objective_ids':ids,'prerequisite_ids':arr(string,uniqueItems=True),'source_refs':arr(source_ref,minItems=1),'cognitive_operation':string,'scenario':string,'expected_reasoning':string,'oracle_id':string,'feedback_by_error':arr(feedback,minItems=1),'hint_policy_id':string,'difficulty_rubric':string,'transfer_variant_id':string,'accessibility_fallback':string,'evidence_rationale':string,'interaction_type':string,'revision':string,'variants':arr(variant,minItems=3),'mode_item_ids':obj({'learning_path':ids,'practice_tutor':ids,'exam_preparation':ids})})
misconception=obj({'misconception_id':string,'objective_ids':ids,'hypothesis':string,'diagnostic_question':string,'remediation_strategy':string,'verification_test_id':string,'status':S('string',enum=['HYPOTHESIS','EVIDENCE_SUPPORTED','REVIEWED'])})
lab=obj({'lab_id':string,'engine_id':string,'course_objective_refs':ids,'scenario_ids':ids,'oracle_ids':ids,'capabilities':ids,'accessibility_fallback':string,'coverage_test_ids':ids,'status':S('string',enum=['PROPOSED','IN_DEVELOPMENT','AVAILABLE','ARCHIVED']),'reuse_decision':S('string',enum=['REUSE','EXTEND','CREATE']),'decision_adr':string,'considered_alternatives':string,'revision':string})
engine=obj({'engine_id':string,'kind':string,'revision':string})
module=obj({'module_id':string,'course_id':string,'objective_ids':ids,'depends_on':arr(string,uniqueItems=True),'acceptance_test_ids':ids,'status':S('string',enum=['PLANNED','IN_PROGRESS','DONE_LOCAL','DONE_TECHNICAL','BLOCKED'])})
route=obj({'route_id':string,'course_id':string,'objective_id':string,'unlock_policy':S('string',enum=['MASTERY','DIAGNOSTIC_EQUIVALENCE']),'mastery_rule':obj({'distinct_variant_families':S('integer',minimum=2),'requires_transfer':S('boolean'),'unassisted_required':S('boolean')}),'diagnostic_oracle_id':S('string'),'diagnostic_evidence_required':S('boolean'),'repeat_access':S('boolean')})
manifest={**base,'properties':{'schema_version':S('string',const='4.1'),'institutions':arr(institution,minItems=1),'sources':arr(source,minItems=1),'courses':arr(course,minItems=1),'objectives':arr(objective,minItems=1),'oracles':arr(oracle,minItems=1),'engines':arr(engine),'misconceptions':arr(misconception,minItems=1),'activities':arr(activity,minItems=1),'labs':arr(lab),'modules':arr(module,minItems=1),'routes':arr(route,minItems=1)},'required':['schema_version','institutions','sources','courses','objectives','oracles','engines','misconceptions','activities','labs','modules','routes']}
mastery_rule=obj({'distinct_variant_families':S('integer',minimum=2),'requires_transfer':S('boolean'),'unassisted_required':S('boolean')})
review_event=obj({'event_id':string,'review_id':string,'kind':S('string',enum=['OPEN','RESOLVE'])})
progress=obj({'user_id':string,'institution_id':string,'course_version':string,'node_id':string,'mastery_rule':mastery_rule,'access_grants':arr(obj({'grant_id':string,'granted_at':string,'evidence_ids':ids}),uniqueItems=True),'mastery_evidence':arr(obj({'evidence_id':string,'variant_family':string,'role':S('string',enum=['PRACTICE','TRANSFER','EXAM','LAB']),'oracle_result':S('string',enum=['VERIFIED','REJECTED','INCONCLUSIVE']),'assisted':S('boolean'),'idempotency_key':string}),uniqueItems=True),'review_events':arr(review_event,uniqueItems=True),'mastery_estimate':S('string',enum=['UNASSESSED','DEVELOPING','MASTERED','NEEDS_REVIEW']),'updated_at':string})
gate=obj({'gate_id':S('string',enum=['G-SOURCE','G-CURRICULUM','G-DESIGN','G-LAB','G-ORACLE','G-PEDAGOGY','G-PROGRESS','G-A11Y','G-SECURITY','G-REGRESSION','G-DEPLOY','G-ACADEMIC','G-EMPIRICAL']),'module_id':string,'input_hash':string,'acceptance_revision':string,'evidence_level':S('string',enum=['E1','E2','E3']),'result':S('string',enum=['DOC_PASS','PASS','FAIL','BLOCKED','NOT_RUN','PENDING_REVIEW']),'commands':arr(string),'logs':arr(string),'observed_at':string,'reviewer':string,'limitations':arr(string),'commit_sha':S('string'),'workflow_run_id':S('string'),'deployment_sha':S('string')})
for name,data in [('manifest.schema.json',manifest),('progress.schema.json',{'$schema':manifest['$schema'],**progress}),('gate.schema.json',{'$schema':manifest['$schema'],**gate})]:
 (SC/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
